 12	    public static void sort(int[] values) {
 13	        Objects.requireNonNull(values, "values");
 14	        sortRange(values, 0, values.length);
 15	    }
 16	
 17	    public static void sort(int[] values, int fromIndex, int toIndexExclusive) {
 18	        Objects.requireNonNull(values, "values");
 19	        sortRange(values, fromIndex, toIndexExclusive);
 20	    }
 21	
 22	    private static void sortRange(int[] values, int fromIndex, int toIndexExclusive) {
 23	        Objects.checkFromToIndex(fromIndex, toIndexExclusive, values.length);
 24	        if (toIndexExclusive - fromIndex < 2) {
 25	            return;
 26	        }
 27	
 28	        quickSort(values, fromIndex, toIndexExclusive);
 29	    }
 30	
 31	    private static void quickSort(int[] values, int left, int rightExclusive) {
 32	        Deque<Range> pendingRanges = new ArrayDeque<>();
 33	        pendingRanges.push(new Range(left, rightExclusive));
 34	
 35	        while (!pendingRanges.isEmpty()) {
 36	            Range range = pendingRanges.pop();
 37	            left = range.left();
 38	            rightExclusive = range.rightExclusive();
 39	
 40	            while (rightExclusive - left > INSERTION_SORT_THRESHOLD) {
 41	                Partition partition = partition(values, left, rightExclusive);
 42	                Range lessThanRange = new Range(left, partition.lessThanEndExclusive());
 43	                Range greaterThanRange = new Range(partition.greaterThanStart(), rightExclusive);
 44	
 45	                if (lessThanRange.length() < greaterThanRange.length()) {
 46	                    if (greaterThanRange.length() > 1) {
 47	                        pendingRanges.push(greaterThanRange);
 48	                    }
 49	                    rightExclusive = lessThanRange.rightExclusive();
 50	                } else {
 51	                    if (lessThanRange.length() > 1) {
 52	                        pendingRanges.push(lessThanRange);
 53	                    }
 54	                    left = greaterThanRange.left();
 55	                }
 56	            }
 57	
 58	            insertionSort(values, left, rightExclusive);
 59	        }
 60	    }
 61	
 62	    private static Partition partition(int[] values, int left, int rightExclusive) {
 63	        int pivot = choosePivotValue(values, left, rightExclusive);
 64	        int lessThan = left;
 65	        int index = left;
 66	        int greaterThan = rightExclusive - 1;
 67	
 68	        while (index <= greaterThan) {
 69	            int current = values[index];
 70	            if (current < pivot) {
 71	                swap(values, lessThan, index);
 72	                lessThan++;
 73	                index++;
 74	            } else if (current > pivot) {
 75	                swap(values, index, greaterThan);
 76	                greaterThan--;
 77	            } else {
 78	                index++;
 79	            }
 80	        }
 81	
 82	        return new Partition(lessThan, greaterThan + 1);
 83	    }
 84	
 85	    private static int choosePivotValue(int[] values, int left, int rightExclusive) {
 86	        int middle = left + ((rightExclusive - left - 1) >>> 1);
 87	        int right = rightExclusive - 1;
 88	
 89	        int leftValue = values[left];
 90	        int middleValue = values[middle];
 91	        int rightValue = values[right];
 92	
 93	        if (leftValue < middleValue) {
 94	            if (middleValue < rightValue) {
 95	                return middleValue;
 96	            }
 97	            return Math.max(leftValue, rightValue);
 98	        }
 99	
100	        if (leftValue < rightValue) {
101	            return leftValue;
102	        }
103	
104	        return Math.max(middleValue, rightValue);
105	    }
106	
107	    private static void insertionSort(int[] values, int left, int rightExclusive) {
108	        for (int index = left + 1; index < rightExclusive; index++) {
109	            int currentValue = values[index];
110	            int position = index - 1;
111	
112	            while (position >= left && values[position] > currentValue) {
113	                values[position + 1] = values[position];
114	                position--;
115	            }
116	
117	            values[position + 1] = currentValue;
118	        }
119	    }
120	
121	    private static void swap(int[] values, int first, int second) {
122	        int temp = values[first];
123	        values[first] = values[second];
124	        values[second] = temp;
125	    }
126	
127	    private record Partition(int lessThanEndExclusive, int greaterThanStart) {}
128	
129	    private record Range(int left, int rightExclusive) {
130	        private int length() {
131	            return rightExclusive - left;
132	        }
133	    }
134	}

